// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 2 );
	const out = new Float64Array( 12 );

	gconvolutionMatrix(); // $ExpectError
	gconvolutionMatrix( 'row-major' ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full' ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2 ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2, 3 ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2, 3, x ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2, 3, x, 1 ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2, 3, x, 1, out ); // $ExpectError
	gconvolutionMatrix( 'row-major', 'full', 2, 3, x, 1, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const x = new Float64Array( 2 );
	const out = new Float64Array( 12 );

	gconvolutionMatrix.ndarray( 'full', 2, 3, x, 1, 0, out, 3, 1, 0 ); // $ExpectType Float64Array
	gconvolutionMatrix.ndarray( 'full', 2, 3, new AccessorArray( x ), 1, 0, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

